// Career and sample-task interactions stay local; live funded work is read from JobsAI.
let toastTimer;
function showToast(message){const node=document.querySelector('#dashboard-toast');node.textContent=message;node.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>node.classList.remove('visible'),2600);}
function toggleSavedRole(id){if(!roles.some(r=>r.id===id))return;const saved=!!state.applications[id];if(saved){delete state.applications[id];delete state.notes?.[id];}else state.applications[id]='Saved';save();renderRoles();renderTracker();showToast(saved?'Removed from your sample board.':'Saved to your board. No application was sent.');}
function downloadSample(filename,data){const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=filename;document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);showToast('Your sample export is ready.');}
const sampleProfileFacts=['Designed a customer onboarding flow.','Conducted customer interviews and research synthesis.','Built interactive prototypes in Figma.','Worked in product and interaction design.','Collaborated with product and engineering partners.','Planned research and presented design decisions.'];
function jumpToMatches(){changeTab('matches');document.querySelector('.workspace-section-head').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'});}
document.querySelector('.dashboard-search').addEventListener('submit',e=>{e.preventDefault();jumpToMatches();renderRoles();});
document.querySelector('#dashboard-search').addEventListener('input',()=>{changeTab('matches');renderRoles();});
document.querySelector('#role-sort').addEventListener('change',renderRoles);
document.querySelectorAll('[data-filter]').forEach(button=>button.addEventListener('click',()=>{document.querySelector('#role-filter').value=button.dataset.filter;renderRoles();}));
document.querySelectorAll('[data-scroll-matches]').forEach(button=>button.addEventListener('click',jumpToMatches));
document.querySelector('#export-board').addEventListener('click',()=>downloadSample('jobsai-sample-board.json',{preview:true,exportedAt:new Date().toISOString(),applications:roles.filter(r=>state.applications[r.id]).map(r=>({role:r.title,company:r.company,stage:state.applications[r.id],note:state.notes?.[r.id]||''}))}));
const dashboardInfo=document.querySelector('#dashboard-info');
const dashboardCopy={
 profile:{title:'Your experience is the starting point.',paragraphs:['Alex Lee is a fictional product designer used in this preview. These six sample profile facts keep the application example grounded.','In the planned product, your profile, documents and application notes are encrypted to your key. This demo does not collect a CV or create a vault.']},
 help:{title:'Make your next move.',paragraphs:['Discover roles: search the four fictional vacancies, compare explained matches, and save a role to your board.','My applications: change a stage, add a local note, or export your sample board. Practice studio: try three interview prompts with a local structure checklist. Work tasks: claim live funded jobs with your wallet, or explore sample templates and local checks. Creation, funding, delivery, and review screens are still being connected.','This is an interactive product preview. No employer application is sent, no AI model is called, and no payment is processed.']},
 privacy:{title:'Your demo stays on this device.',paragraphs:['This workspace stores sample application stages, notes, and task choices in your browser. Wallet sign-in stores a session token in this browser tab so it can claim a live funded job. Interview answers are not uploaded or saved.','Reset sample data clears those demo changes and restores the initial examples. No passkey, CV vault, telemetry, or model processor is connected here. Wallet sign-in is used only for live job claims; the token stays in this browser tab.','Planned career profiles, recovery and export tools are not connected. Live job submissions and dispute records remain stored after settlement; automatic deletion after 30 days is planned, but not active. Uploaded images follow the image-storage account’s retention settings.']},
 pass:{title:'Career Pass, planned at $9/month.',paragraphs:['The planned pass includes 60 tailored applications per month, unlimited mock interviews and role-relevant practice tasks. The daily application limit is 10.','A full refund applies within 14 days of the first payment. After that, unused full months are refunded at the price actually paid. Application packs are planned at $4 for five documents; each document passes before a credit counts.','Pricing comes from the product specification. There is no live subscription or checkout in this preview.']}
};
function openDashboardInfo(kind){const copy=dashboardCopy[kind]||dashboardCopy.help;document.querySelector('#dashboard-info-title').textContent=copy.title;const body=document.querySelector('#dashboard-info-body'),actions=document.querySelector('#dashboard-info-actions');body.replaceChildren(...copy.paragraphs.map(t=>el('p',t)));actions.replaceChildren();if(kind==='profile'){const list=el('ul',undefined,'profile-facts');sampleProfileFacts.forEach(t=>list.append(el('li',t)));body.prepend(list);const exportButton=el('button','Export sample profile ↓','pill primary');exportButton.addEventListener('click',()=>downloadSample('jobsai-sample-profile.json',{preview:true,name:'Alex Lee',facts:sampleProfileFacts}));actions.append(exportButton);}if(kind==='help'||kind==='privacy'){const reset=el('button','Reset sample data','pill outline');reset.addEventListener('click',()=>{document.querySelector('#reset-demo').click();dashboardInfo.close();showToast('Sample data restored.');});actions.append(reset);}const close=el('button','Got it','pill primary');close.addEventListener('click',()=>dashboardInfo.close());actions.append(close);dashboardInfo.showModal();}
document.querySelectorAll('[data-dashboard-info]').forEach(button=>button.addEventListener('click',()=>openDashboardInfo(button.dataset.dashboardInfo)));
dashboardInfo.querySelector('.dialog-close').addEventListener('click',()=>dashboardInfo.close());
dashboardInfo.addEventListener('click',e=>{if(e.target!==dashboardInfo)return;const r=dashboardInfo.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dashboardInfo.close();});
document.addEventListener('jobsai:tab',()=>{const main=document.querySelector('#workspace-main');main.setAttribute('tabindex','-1');const top=main.getBoundingClientRect().top+window.scrollY-210;if(window.scrollY>Math.max(0,top))window.scrollTo({top:Math.max(0,top),behavior:'instant'});});
renderRoles();
